function consume(bucket, nowMs) {
  // TODO: compute refilled tokens (capped at capacity), then consume one
  // if refilled >= 1. Return { ...bucket, tokens, lastRefillMs: nowMs, allowed }.
}

items.solution:
function consume(bucket, nowMs) {
  const elapsedSeconds = Math.max(0, (nowMs - bucket.lastRefillMs) / 1000);
  const refilled = Math.min(
    bucket.capacity,
    bucket.tokens + elapsedSeconds * bucket.refillPerSecond,
  );

  if (refilled < 1) {
    return { ...bucket, tokens: refilled, lastRefillMs: nowMs, allowed: false };
  }

  return { ...bucket, tokens: refilled - 1, lastRefillMs: nowMs, allowed: true };
}

