}

items.solution:
function assertNoCrossTenantRows(rows, tenantId) {
  const leaked = rows.filter((row) => row.tenantId !== tenantId);
  if (leaked.length > 0) {
    throw new Error(`${leaked.length} row(s) leaked from another tenant`);
  }
  return true;
}

